<?php require __DIR__.'/includes/bootstrap.php';$cart=$_SESSION['cart']??[];if(!$cart){header('Location: cart.php');exit;}$ids=array_keys($cart);$marks=implode(',',array_fill(0,count($ids),'?'));$s=$pdo->prepare("SELECT * FROM products WHERE active=1 AND id IN ($marks)");$s->execute($ids);$items=$s->fetchAll();$total=0;foreach($items as $p)$total+=$p['price']*$cart[$p['id']];$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim($_POST['customer_name']??'');$phone=trim($_POST['phone']??'');$city=trim($_POST['city']??'');$address=trim($_POST['address']??'');$notes=trim($_POST['notes']??'');if($name===''||$phone===''||$city==='')$error='يرجى تعبئة الاسم ورقم الجوال والمدينة.';else{try{$pdo->beginTransaction();$s=$pdo->prepare('INSERT INTO orders(customer_name,phone,city,address,notes,total,status) VALUES(?,?,?,?,?,?,?)');$s->execute([$name,$phone,$city,$address,$notes,$total,'جديد']);$orderId=(int)$pdo->lastInsertId();$d=$pdo->prepare('INSERT INTO order_items(order_id,product_id,product_name,price,quantity) VALUES(?,?,?,?,?)');foreach($items as $p)$d->execute([$orderId,$p['id'],$p['name'],$p['price'],$cart[$p['id']]]);$pdo->commit();unset($_SESSION['cart']);header('Location: order-success.php?id='.$orderId);exit;}catch(Throwable $e){$pdo->rollBack();$error='تعذر حفظ الطلب. حاول مرة أخرى.';}}}
$page_title='إتمام الطلب';require __DIR__.'/includes/header.php'; ?><main class="container"><h1 class="gold">إتمام الطلب</h1><div class="panel"><p>الإجمالي: <strong class="price"><?=money($total)?></strong></p><?php if($error): ?><div class="alert"><?=e($error)?></div><?php endif; ?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="form-grid"><div class="field"><label>الاسم الكامل *</label><input name="customer_name" required></div><div class="field"><label>رقم الجوال *</label><input name="phone" type="tel" required></div><div class="field"><label>المدينة *</label><input name="city" required></div><div class="field"><label>العنوان</label><input name="address"></div></div><div class="field"><label>ملاحظات إضافية</label><textarea name="notes"></textarea></div><button class="btn">تأكيد الطلب</button></form></div></main><?php require __DIR__.'/includes/footer.php'; ?>
